const KEY = 'consent';
const stored = localStorage.getItem(KEY);
if (!stored) showBanner();

function decide(categories) {
  localStorage.setItem(KEY, JSON.stringify({ categories, at: Date.now() }));
  document.cookie = `${KEY}=${encodeURIComponent(categories.join(','))}; path=/; max-age=15552000`;
  hideBanner();
}
